begin;
create extension if not exists pgtap with schema extensions;
select plan(21);
select is((select count(*) from pg_class where relname in ('suppliers','supplier_commands') and relrowsecurity),2::bigint,'Supplier tables enable RLS');
select ok((select not rolcanlogin and not rolbypassrls from pg_roles where rolname='suppliers_writer'),'writer is isolated nologin');
select ok(not has_table_privilege('anon','public.suppliers','SELECT'),'anon cannot read supplier contact data');
select ok(not has_table_privilege('authenticated','public.suppliers','SELECT'),'direct clients cannot bypass API permission checks');
select ok(not has_table_privilege('authenticated','public.suppliers','INSERT'),'clients cannot create');
select ok(not has_table_privilege('authenticated','public.suppliers','UPDATE'),'clients cannot edit or deactivate');
select ok(not has_table_privilege('authenticated','public.suppliers','DELETE'),'clients cannot delete');
select ok(not has_table_privilege('service_role','public.suppliers','INSERT'),'transport cannot directly create');
select ok(not has_table_privilege('service_role','public.suppliers','UPDATE'),'transport cannot directly update');
select ok(not has_table_privilege('service_role','public.suppliers','DELETE'),'transport cannot delete');
select ok(not has_table_privilege('service_role','public.supplier_commands','SELECT'),'command intent is private');
select ok(not has_function_privilege('authenticated','suppliers_private.write_supplier(uuid,uuid,uuid,text,jsonb)','EXECUTE'),'client cannot invoke writer');
select ok(has_function_privilege('service_role','suppliers_private.write_supplier(uuid,uuid,uuid,text,jsonb)','EXECUTE'),'transport can invoke authorized path');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='suppliers_private' and p.proname not in ('supplier_json','reminder_json') and (not p.prosecdef or not p.proconfig @> array['search_path=""'])),0::bigint,'entrypoints have hardened search path');
select ok(not has_table_privilege('suppliers_writer','public.inventory_operations','INSERT'),'supplier writer cannot create inventory');
select ok(not has_table_privilege('suppliers_writer','public.inventory_movements','UPDATE'),'supplier writer cannot change movement history');
select ok(not has_table_privilege('service_role','public.inventory_operations','UPDATE'),'transport cannot rewrite supplier snapshots');
select ok(not has_function_privilege('authenticated','inventory_private.record_operation(uuid,text,jsonb,uuid,text,timestamptz,text,uuid,text)','EXECUTE'),'client cannot invoke receiving');
select ok(has_function_privilege('service_role','inventory_private.record_operation(uuid,text,jsonb,uuid,text,timestamptz,text,uuid,text)','EXECUTE'),'receipt overload callable by transport');
select is((select count(*) from pg_constraint where conname='inventory_operations_supplier_tenant_fk' and contype='f' and confdeltype='r'),1::bigint,'composite FK restricts supplier deletion');
select is((select count(*) from pg_policy where polrelid='public.suppliers'::regclass and polcmd in ('a','w','d','*')),0::bigint,'no client mutation policy');
select * from finish();
rollback;
